// Truchet tiles: every square holds two quarter-circle arcs on opposite corners. Turned a
// quarter turn, a tile swaps which corners its arcs join, so side by side they make long
// winding paths. A wave sweeps across the grid and smoothly turns the tiles it passes.
#define PI 3.14159265

// A pseudo-random number for each tile.
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// The distance to a quarter circle of radius 0.5 around the origin, joining (0.5, 0) and
// (0, 0.5). Outside that quarter, it's the distance to the nearer end, giving round ends.
float quarterArc(vec2 q) {
  if (q.x > 0.0 && q.y > 0.0) {
    return abs(length(q) - 0.5);
  }
  return min(length(q - vec2(0.5, 0.0)), length(q - vec2(0.0, 0.5)));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Coordinates with (0, 0) in the middle, and y from -1 to 1.
  vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

  // Split the screen into tiles, drifting slowly to the left.
  float scale = 5.0;
  vec2 p = uv * scale + vec2(0.4 * iTime, 0.0);
  vec2 tile = floor(p);
  vec2 f = fract(p) - 0.5;

  // How far this tile has turned, in quarter turns: a random start, plus a smooth extra
  // quarter turn while the wave passes over it.
  float wave = sin(0.8 * iTime - 0.35 * (tile.x + 0.5 * tile.y));
  float turns = floor(2.0 * hash(tile)) + smoothstep(-0.4, 0.4, wave);
  float angle = 0.5 * PI * turns;
  f = mat2(cos(angle), sin(angle), -sin(angle), cos(angle)) * f;
  // Shrink the arcs a little mid-turn, so they stay inside their square.
  f *= 1.0 + 0.35 * sin(PI * fract(turns));

  // The distance to the nearer arc. The arcs are centred on opposite corners.
  float d = min(quarterArc(0.5 - f), quarterArc(0.5 + f));
  float pixel = 2.0 * scale / iResolution.y;
  float line = smoothstep(0.12 + pixel, 0.12, d);

  // Colour by position on the screen, so it flows smoothly across the tiles.
  vec3 background = vec3(0.06, 0.07, 0.12);
  float shade = 0.08 * (p.x - p.y) - 0.05 * iTime;
  vec3 lineColor = 0.6 + 0.4 * cos(2.0 * PI * (shade + vec3(0.0, 0.15, 0.3)));
  fragColor = vec4(mix(background, lineColor, line), 1.0);
}
